pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 balance, uint256 unlockTime, uint256 warpTime) public {
        uint256 b = bound(balance, 1 ether, 100 ether);
        uint256 t = bound(warpTime, 1, 1000000);
        uint256 u = bound(unlockTime, 0, 999999);

        address actor = address(0x1234);
        vm.deal(actor, b);
        vm.warp(t);

        vm.prank(actor);
        c.Put{value: b}(u);

        uint256 unlock = t + u + 1;
        vm.warp(unlock + 1);

        vm.prank(actor);
        c.Collect(b);

        ( , uint256 bal) = c.Acc(actor);
        assertTrue(bal == 0);
    }
}
